entries[1226650] = { ["name"] = "Leerenkristallpanther", ["text"] = "Wirken in 2 sek. 2\nTools: Juwelierswerkzeuge\nReagenzien:\nLeerengebundene Kugel der Geheimnisse , Ungewöhnliche Edelsteine , Schattenerfüllter Onyx (20), Schwarzbluterfüllte Stange (4)\nBeute:\nKeech der Große\nZone:\nVision von Orgrimmar\n\nLeerenkristallpanther\nWird an Kriegsmeute gebunden\nReittier (Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier fliegt oder läuft in Abhängigkeit von Eurer Reitfertigkeit und Eurem Aufenthaltsort.\nBeschwört einen reitbaren Leerenkristallpanther oder gibt ihn wieder frei.\n1 - 80 ( 80)\nBenötigt Unerfahrenes Reiten\n\"Obwohl viele kostbare Edelsteine in verstörenden Visionen von den Leerenenergien verderbt wurden, können Juwelierskunstmeister sie immer noch verwenden, um mächtige Pantherrösser herzustellen.\"\nBeruf:\nJuwelierskunst" }
entries[1226659] = { ["name"] = "Dunkler Stern", ["text"] = "Unbegrenzte Reichweite\nSofort\nEin Stern materialisiert sich aus dem Wirbelnden Nether und zieht Spielercharaktere 5 Sek. lang in sein Zentrum.\n\nWährend des Entstehungsprozesses werden Spielercharaktere innerhalb von ' Dunkler Stern ' ' Atomisiert ', während ' Zwielichtstacheln ' nach außen ausstrahlt. Fügt allen Spielercharakteren alle 1 Sek. 56215 kosmischen Schaden zu." }
