entries[1228865] = { ["name"] = "Leerenvernarbter Luchs", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Das Zähmen von Luchsen ist eine Praktik, die die Arathi seit Jahren verfeinert haben. Während die Kultisten von Nachtsturz ihrer Sache treu ergeben bleiben, geben sie diese Tradition dennoch weiter.\"\nBeute.\nKonfiszierte Kultistentasche" }
