entries[1229032] = { ["name"] = "Matsch!", ["text"] = "Sofort\nDas Ziel wird gegen eine Wand geschleudert und erleidet 168 körperlichen Schaden. Dieser Schaden wird verringert, je weiter der Spielercharakter sich bewegt." }
entries[1229033] = { ["name"] = "Schwerkraftschmettern", ["text"] = "12 Meter Reichweite\nWirken in 3.4 sek.\nDrischt auf den Boden, um einen kleinen Leerenriss zu erzeugen. Fügt allen Gegnern innerhalb von 6 Metern um den Treffer Schattenschaden zu und zieht sie 6 Sek. lang dorthin." }
