entries[1229185] = { ["name"] = "Astraler Energieumwandler", ["text"] = "Wenn die Gesundheit eines Gruppenmitglieds unter 60% sinkt, materialisiert sich ein astraler Energieumwandler, der Gegnern in der Nähe moderaten Schaden zufügt und diese 4 Sek. lang verspottet. Nach Ablauf des Spotts entfesselt der Umwandler eine Ätherwelle, die Verbündete in der Nähe um 20% ihrer Gesundheit heilt. Kann alle 2 Min. ausgelöst werden. Das Töten von Gegnern reduziert die Abklingzeit dieses Effekts um 2 Sek." }
