entries[1229189] = { ["name"] = "Managetönte Brille", ["text"] = "Brann setzt während des Kampfes eine managetönte Brille auf, die alle 5 Sek. seinen verursachten Schaden um 4 % und seinen erlittenen Schaden um 5 % erhöht, bis zu 10-mal.\n\nWird die Brille gebannt, heilt Brann sich um 25 % seiner maximalen Gesundheit und betäubt Gegner in der Nähe für 2 Sek.\nAndernfalls wird dieser Effekt automatisch gebannt, wenn Branns Gesundheit unter 30 % sinkt, wodurch die Betäubung verhindert wird." }
entries[1229190] = { ["name"] = "Managetönte Brille", ["text"] = "Brann setzt während des Kampfes eine managetönte Brille auf, die alle 5 Sek. seinen verursachten Schaden um 4% und seinen erlittenen Schaden um 5% erhöht, bis zu 10-mal.\n\nWird die Brille gebannt, heilt Brann sich um 40% seiner maximalen Gesundheit und betäubt Gegner in der Nähe für 3 Sek.\nAndernfalls wird dieser Effekt automatisch gebannt, wenn Branns Gesundheit unter 30% sinkt, wodurch die Betäubung verhindert wird." }
