entries[1229197] = { ["name"] = "Hatarang", ["text"] = "Brann hat eine Chance, zufällig ausgewählte Hüte hervorzuziehen und sie auf seine Gegner zu werfen, wodurch er mäßigen Schaden verursacht und 1 Schwächungseffekt auf 2 Ziele anwendet.\n\nMögliche Schwächungseffekte sind eine Erhöhung des erlittenen Schadens um 20%, eine Verringerung des verursachten Schadens um 20% sowie eine Verringerung des Angriffs- und Zaubertempos um 20%." }
