entries[1229246] = { ["name"] = "Heiliger Sturmangriff", ["text"] = "Sofort\nDer Schutz durch 'Heilige Flamme' ist jetzt 50% effektiver.\n\nSchutz der Heiligen Flamme :\nWährend Ihr Euch in Khaz Algar befindet, besteht beim Verursachen von Schaden eine hohe Chance, den Gegner mit rechtschaffenem Feuer zu verbrennen und ihm so 2 Strahlenschaden zuzufügen. Außerdem erleidet Ihr 5% weniger Schaden." }
entries[1229247] = { ["name"] = "Heiliger Sturmangriff", ["text"] = "Sofort\nDer Schutz durch 'Heilige Flamme' ist jetzt 100% effektiver, hoch von 50%.\n\nSchutz der Heiligen Flamme :\nWährend Ihr Euch in Khaz Algar befindet, besteht beim Verursachen von Schaden eine hohe Chance, den Gegner mit rechtschaffenem Feuer zu verbrennen und ihm so 2 Strahlenschaden zuzufügen. Außerdem erleidet Ihr 5% weniger Schaden." }
entries[1229261] = { ["name"] = "Rückenwindleiter", ["text"] = "Unbegrenzte Reichweite\nSofort\nVerleiht beim Verlassen des Kampfes einen Geschwindigkeitsschub, der Eure Bewegungsgeschwindigkeit 10 Sek. lang um 40% erhöht. Nimmt mit der Zeit ab. Wenn Ihr im Kampf eine Defensivfähigkeit einsetzt, werdet Ihr von Windstößen eingehüllt, die Euch 8 Sek. lang einen Schild in Höhe von 20% Eurer verlorenen Gesundheit verleihen.\n(30s Abklingzeit)" }
