entries[1230309] = { ["name"] = "Temporalentschleunigungskristall", ["text"] = "Unbegrenzte Reichweite\nSofort\nWenn Ihr einem Elitegegner mit 80% oder mehr sowie mit 20% oder weniger Gesundheit Schaden zufügt, löst Brann die Energien des Kristalls aus. Dies verringert das Angriffs- und Zaubertempo des Elitegegners 30 Sek. lang um 20%. Wird der betroffene Elitegegner getötet, während der Schwächungseffekt aktiv ist, erhält die Gruppe eine stapelbare Tempostärkung von 2%." }
